/**
 * Read the userId/frontendToken that `initializeAuth()` writes on success.
 * The SDK never reads these back when an `aos_temp_token` is present in the
 * URL but its exchange fails — it returns `{ null, null }` and skips the
 * localStorage path entirely. That strands users in a "Not authenticated"
 * banner even when they have a perfectly valid prior session cached.
 *
 * Our backend endpoints (/api/photo-stream, /api/take-photo) only need
 * `userId`, so falling back to the cached value unblocks the UI.
 */
function readLocalAuthFallback(): { userId: string; frontendToken: string } | null {
  if (typeof window === "undefined") return null;
  try {
    const userId = localStorage.getItem("mentra_user_id") || "";
    const frontendToken = localStorage.getItem("mentra_frontend_token") || "";
    if (!userId) return null;
    return { userId, frontendToken };
  } catch {
    return null;
  }
}

export default function App() {
  const {
    userId: sdkUserId,
    frontendToken: sdkFrontendToken,
    isLoading,
    error,
    isAuthenticated: sdkIsAuthenticated,
  } = useMentraAuth();

  // Fallback: when the SDK comes back empty but localStorage holds a prior
  // session's userId, use it. We treat a localStorage-derived auth as
  // authenticated *for our app's purposes* — the API endpoints we call
  // only need userId — but log it so we know we're in the fallback path.
  const fallback = !sdkUserId ? readLocalAuthFallback() : null;
  const userId = sdkUserId || fallback?.userId || null;
  const frontendToken = sdkFrontendToken || fallback?.frontendToken || null;
  const isAuthenticated = sdkIsAuthenticated || (!!fallback && !!fallback.userId);

  if (fallback && typeof window !== "undefined" && !(window as any).__mentraFallbackLogged) {
    (window as any).__mentraFallbackLogged = true;
    console.log(
      "[App] useMentraAuth returned empty; using localStorage fallback userId:",
      fallback.userId,
    );
  }

