tool_input.content:
#!/usr/bin/env node
// Photo end-to-end smoke test for MentraOS-Camera-Example-App.
//
// Exercises the full flow that times out in production:
//   1) Tunnel reachability (HTTP and HTTPS, the same URL the cloud hands the
//      glasses).
//   2) /photo-upload acceptance with a synthetic JPEG payload — proves the
//      SDK photo-upload bridge is wired up. A missing requestId should come
//      back as 404 ("no pending request"); that is the "healthy" outcome
//      because we did not register one.
//   3) End-to-end: trigger /take-photo on the example app, then watch
//      /photo-stream (SSE) for the photo to actually arrive. Anything other
//      than success here means the cloud→glasses BLE delivery, the camera
//      capture, or the glasses→tunnel HTTPS upload is broken — and step 1+2
//      tell us which one.
//
// Usage (from MentraOS-Camera-Example-App/):
//   node smoke-test/photo-e2e.mjs                 # uses .env
//   node smoke-test/photo-e2e.mjs --user me@x.com # override user id
//   PUBLIC_URL=... LOCAL_APP_URL=http://localhost:3300 node smoke-test/photo-e2e.mjs
//
// Exit code is the number of failed checks, so this is CI-friendly.

import { readFileSync, existsSync } from "node:fs"
import { fileURLToPath } from "node:url"
import { dirname, resolve } from "node:path"
import { setTimeout as delay } from "node:timers/promises"

const here = dirname(fileURLToPath(import.meta.url))
const repoRoot = resolve(here, "..")

// --- minimal .env loader (no dependencies) -------------------------------
function loadEnvFile(p) {
  if (!existsSync(p)) return {}
  const out = {}
  for (const raw of readFileSync(p, "utf8").split("\n")) {
    const line = raw.trim()
    if (!line || line.startsWith("#")) continue
    const eq = line.indexOf("=")
    if (eq < 0) continue
    const k = line.slice(0, eq).trim()
    let v = line.slice(eq + 1).trim()
    if ((v.startsWith('"') && v.endsWith('"')) || (v.startsWith("'") && v.endsWith("'"))) {
      v = v.slice(1, -1)
    }
    out[k] = v
  }
  return out
}
const fileEnv = loadEnvFile(resolve(repoRoot, ".env"))
const env = (k, fallback) => process.env[k] ?? fileEnv[k] ?? fallback

// --- args ---------------------------------------------------------------
const args = process.argv.slice(2)
const argMap = Object.fromEntries(
  args
    .map((a, i) => (a.startsWith("--") ? [a.replace(/^--/, ""), args[i + 1] ?? "true"] : null))
    .filter(Boolean),
)

const PUBLIC_URL = (argMap.publicUrl ?? env("PUBLIC_URL", "")).replace(/\/+$/, "")
const LOCAL_APP_URL = (argMap.localAppUrl ?? env("LOCAL_APP_URL", `http://localhost:${env("PORT", "3300")}`)).replace(/\/+$/, "")
const USER_ID = argMap.user ?? env("SMOKE_USER_ID", "smoke-test@example.com")
const TIMEOUT_MS = Number(argMap.timeoutMs ?? env("SMOKE_TIMEOUT_MS", "45000"))

if (!PUBLIC_URL) {
  console.error("✖ PUBLIC_URL is not set (in .env or --publicUrl).")
  process.exit(2)
}

// --- pretty logging -----------------------------------------------------
const c = (code, s) => `\x1b[${code}m${s}\x1b[0m`
const ok = (m) => console.log(`${c("32", "✓")} ${m}`)
const warn = (m) => console.log(`${c("33", "!")} ${m}`)
const fail = (m) => console.log(`${c("31", "✖")} ${m}`)
const head = (m) => console.log("\n" + c("1", m))
const dim = (m) => console.log(c("2", `  ${m}`))

let failures = 0
const failed = (m) => {
  failures++
  fail(m)
}

// --- helpers ------------------------------------------------------------
async function fetchWithTimeout(url, init = {}, ms = 8000) {
  const ctrl = new AbortController()
  const t = setTimeout(() => ctrl.abort(new Error(`timeout after ${ms}ms`)), ms)
  try {
    return await fetch(url, { ...init, signal: ctrl.signal })
  } finally {
    clearTimeout(t)
  }
}

// 320x240 grey JPEG header — small enough for the test, big enough that
// servers don't reject it as empty. Generated once and reused.
function syntheticJpeg() {
  // Tiny valid JPEG (1x1 black pixel) — 125 bytes.
  return Buffer.from(
    "",
    "hex",
  )
}

// --- 1. tunnel reachability --------------------------------------------
async function step1_tunnel() {
  head("Step 1: tunnel reachability")
  const variants = [
    { url: PUBLIC_URL, label: "PUBLIC_URL (configured)" },
    PUBLIC_URL.startsWith("https://")
      ? { url: PUBLIC_URL.replace(/^https/, "http"), label: "http variant" }
      : { url: PUBLIC_URL.replace(/^http/, "https"), label: "https variant" },
  ]
  for (const v of variants) {
    try {
      const res = await fetchWithTimeout(`${v.url}/photo-upload`, { method: "GET", redirect: "manual" }, 8000)
      if (res.status === 404 || res.status === 405 || res.status === 200 || res.status === 301 || res.status === 308) {
        ok(`${v.label}: ${v.url} reachable (HTTP ${res.status})`)
      } else {
        warn(`${v.label}: ${v.url} reachable but returned HTTP ${res.status} (unexpected, but tunnel is up)`)
      }
    } catch (e) {
      const msg = e?.cause?.message || e?.message || String(e)
      failed(`${v.label}: ${v.url} unreachable — ${msg}`)
      if (msg.includes("certificate") || msg.includes("SSL") || msg.includes("TLS")) {
        dim("→ TLS chain rejected. Glasses on older Android may also fail this. Try the http variant of PUBLIC_URL.")
      }
    }
  }
}

// --- 2. /photo-upload accepts a multipart payload ----------------------
async function step2_uploadEndpoint() {
  head("Step 2: /photo-upload accepts a (synthetic) glasses upload")
  const target = `${PUBLIC_URL}/photo-upload`
  const fakeRequestId = `smoke_${Date.now()}`
  try {
    const form = new FormData()
    form.append("requestId", fakeRequestId)
    form.append("type", "photo_upload")
    form.append("success", "true")
    form.append(
      "photo",
      new Blob([syntheticJpeg()], { type: "image/jpeg" }),
      "smoke.jpg",
    )
    const res = await fetchWithTimeout(target, { method: "POST", body: form }, 10000)
    const body = await res.text().catch(() => "")
    if (res.status === 404) {
      ok(`/photo-upload responded 404 — SDK bridge is wired up (no pending request for ${fakeRequestId} is the expected outcome).`)
    } else if (res.status >= 200 && res.status < 300) {
      warn(`/photo-upload returned HTTP ${res.status}. Unexpected for an unregistered requestId — check the SDK photo bridge.`)
      dim(`body: ${body.slice(0, 200)}`)
    } else {
      failed(`/photo-upload returned HTTP ${res.status} ${res.statusText}`)
      dim(`body: ${body.slice(0, 200)}`)
    }
  } catch (e) {
    failed(`/photo-upload unreachable: ${e?.cause?.message || e?.message || e}`)
  }
}

// --- 3. end-to-end via local /take-photo + /photo-stream SSE ----------
async function step3_endToEnd() {
  head(`Step 3: end-to-end take-photo via local example app (${LOCAL_APP_URL})`)
  // SSE listener first, so we don't miss the broadcast.
  const sseCtrl = new AbortController()
  let gotPhoto = null
  const ssePromise = (async () => {
    try {
      const res = await fetch(`${LOCAL_APP_URL}/photo-stream?userId=${encodeURIComponent(USER_ID)}`, {
        signal: sseCtrl.signal,
      })
      if (!res.ok) throw new Error(`SSE stream HTTP ${res.status}`)
      const reader = res.body.getReader()
      const decoder = new TextDecoder()
      let buf = ""
      while (true) {
        const { value, done } = await reader.read()
        if (done) break
        buf += decoder.decode(value, { stream: true })
        // SSE message frames are separated by blank lines. We only care that
        // a `data:` payload landed for our user.
        const events = buf.split(/\n\n/)
        buf = events.pop() ?? ""
        for (const ev of events) {
          const dataLine = ev
            .split("\n")
            .find((l) => l.startsWith("data:"))
          if (!dataLine) continue
          try {
            const obj = JSON.parse(dataLine.slice(5).trim())
            if (obj && obj.requestId) {
              gotPhoto = obj
              return
            }
          } catch {
            /* keepalive lines etc. */
          }
        }
      }
    } catch (e) {
      if (e?.name !== "AbortError") {
        dim(`(SSE error: ${e?.message || e})`)
      }
    }
  })()

  // Trigger the capture.
  let triggerOk = false
  try {
    const res = await fetchWithTimeout(
      `${LOCAL_APP_URL}/take-photo`,
      {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ userId: USER_ID }),
      },
      35_000, // example app's takePhoto wraps the SDK's 30s timer plus probe overhead
    )
    const body = await res.text().catch(() => "")
    if (res.ok) {
      ok(`POST /take-photo accepted (HTTP ${res.status})`)
      triggerOk = true
    } else if (res.status === 404 || res.status === 409) {
      failed(`POST /take-photo refused (HTTP ${res.status}) — example app has no glasses session for ${USER_ID}.`)
      dim(`body: ${body.slice(0, 200)}`)
      dim("→ Make sure the user's glasses are paired and the app is running on them BEFORE running this script.")
    } else {
      failed(`POST /take-photo failed (HTTP ${res.status}): ${body.slice(0, 200)}`)
    }
  } catch (e) {
    const msg = e?.cause?.message || e?.message || String(e)
    failed(`POST /take-photo errored: ${msg}`)
    dim("→ The example app itself responded with an error. The most common ones:")
    dim("    • 'Photo request timed out (30s)' — cloud→glasses→tunnel chain broke (the bug we're chasing)")
    dim("    • ECONNREFUSED — example app isn't running locally; start it with `bun run dev`.")
  }

  if (triggerOk) {
    // Wait for the SSE photo or timeout.
    const start = Date.now()
    while (!gotPhoto && Date.now() - start < TIMEOUT_MS) {
      await delay(250)
    }
    sseCtrl.abort()
    await ssePromise.catch(() => {})

    if (gotPhoto) {
      ok(
        `Photo arrived end-to-end via SSE in ${Date.now() - start}ms ` +
          `(requestId=${gotPhoto.requestId}, ${gotPhoto.size ?? "?"} bytes, mime=${gotPhoto.mimeType ?? "?"}).`,
      )
    } else {
      failed(
        `No photo broadcast on /photo-stream within ${TIMEOUT_MS}ms after a successful trigger — the cloud→glasses→tunnel→app chain is broken.`,
      )
      dim("Likely culprits, in priority order:")
      dim("  1) Glasses can't reach the tunnel from their WiFi (TLS, DNS, captive portal). Use adb logcat -v time AsgClient:V MediaCaptureService:V *:E.")
      dim("  2) Mobile core never relayed PHOTO_REQUEST to glasses (cloud→phone WS or phone→glasses BLE).")
      dim("  3) Camera capture rejected on the glasses (CAMERA_BUSY / BATTERY_LOW / INSUFFICIENT_STORAGE).")
    }
  }
}

// --- main ---------------------------------------------------------------
console.log(c("1", "MentraOS Photo End-to-End Smoke Test"))
dim(`PUBLIC_URL=${PUBLIC_URL}`)
dim(`LOCAL_APP_URL=${LOCAL_APP_URL}`)
dim(`USER_ID=${USER_ID}`)
dim(`TIMEOUT_MS=${TIMEOUT_MS}`)

await step1_tunnel()
await step2_uploadEndpoint()
await step3_endToEnd()

console.log("")
if (failures === 0) {
  ok("All smoke checks passed.")
  process.exit(0)
} else {
  fail(`${failures} smoke check${failures === 1 ? "" : "s"} failed.`)
  process.exit(failures > 125 ? 125 : failures)
}

